import java.util.ArrayList;
import java.util.List;

public class Catalogo {

    private final List<String> linguagens = new ArrayList<String>();

    public void adicionar(String linguagem) {
        linguagens.add(linguagem);
    }

    public int tamanho() {
        return linguagens.size();
    }

    public List<String> listar() {
        return linguagens;
    }
}

public class Principal {

    public static void main(String[] args) {
        Catalogo catalogo = new Catalogo();
        catalogo.adicionar("tupi");
        catalogo.adicionar("guarani");
        catalogo.adicionar("nheengatu");
        System.out.println("Linguagens no catálogo: " + catalogo.tamanho());
        System.out.println("Lista: " + catalogo.listar());
    }
}
